<?php namespace App\Console\Commands;use Illuminate\Console\Command;use App\Models\{Order,LoyaltyAccount,LoyaltyTransaction};class AwardLoyaltyPoints extends Command{protected $signature='shoply:loyalty';protected $description='Award one point per NGN 100 on newly delivered paid orders.';public function handle(){Order::where('status','delivered')->where('payment_status','paid')->whereDoesntHave('loyaltyTransaction')->chunkById(100,function($orders){foreach($orders as $o){$a=LoyaltyAccount::firstOrCreate(['user_id'=>$o->user_id]);$points=(int)floor($o->total/100);if($points<1)continue;$a->increment('points',$points);LoyaltyTransaction::create(['loyalty_account_id'=>$a->id,'points'=>$points,'type'=>'earned','reference'=>$o->number,'description'=>'Delivered order reward']);}});$this->info('Loyalty points awarded.');return self::SUCCESS;}}
